import{_ as e,o as d,c as a,a0 as r}from"./chunks/framework.DQOulFGV.js";const k=JSON.parse('{"title":"写给 restic 用户","description":"Keelhaven 是 restic 的 macOS 原生菜单栏前端。它到底执行了哪些 restic 命令，怎么接入你已有的仓库，哪些事它有意留给命令行。","frontmatter":{"title":"写给 restic 用户","description":"Keelhaven 是 restic 的 macOS 原生菜单栏前端。它到底执行了哪些 restic 命令，怎么接入你已有的仓库，哪些事它有意留给命令行。"},"headers":[],"relativePath":"zh/restic.md","filePath":"zh/restic.md"}'),o={name:"zh/restic.md"};function s(c,t,i,l,n,h){return d(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="写给-restic-用户" tabindex="-1">写给 restic 用户 <a class="header-anchor" href="#写给-restic-用户" aria-label="Permalink to &quot;写给 restic 用户&quot;">​</a></h1><p>Keelhaven 是前端，不是分支。它内置原版 restic（0.19.1），以子进程方式运行， 写出来的就是普通的 restic 仓库。它做的每件事你都可以自己敲命令完成，它补上 的是定时、钥匙串和菜单栏。</p><h2 id="它执行了什么" tabindex="-1">它执行了什么 <a class="header-anchor" href="#它执行了什么" aria-label="Permalink to &quot;它执行了什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>什么时候</th><th>命令</th></tr></thead><tbody><tr><td>新建计划</td><td><code>restic init</code></td></tr><tr><td>每次定时运行</td><td><code>restic backup --json --tag keelhaven &lt;文件夹&gt;</code></td></tr><tr><td>保留策略，备份成功后执行，最多每周一次</td><td><code>restic forget --prune --tag keelhaven --keep-…</code></td></tr><tr><td>验证，默认每周</td><td><code>restic check</code></td></tr><tr><td>打开快照挑选文件</td><td><code>restic ls &lt;快照&gt; --json</code></td></tr><tr><td>恢复</td><td><code>restic restore &lt;快照&gt; --target &lt;新文件夹&gt;</code>，你选了哪些文件或文件夹，就各加一个 <code>--include &lt;路径&gt;</code></td></tr><tr><td>你要求清理残留的锁时</td><td><code>restic unlock</code>，从不带 <code>--remove-all</code></td></tr></tbody></table><p>整个应用同一时间只跑一个 restic 进程。<code>forget</code> 上的 <code>--tag</code> 是 0.9.2 加的， 为什么要紧，见下面「接入已有的仓库」。</p><p>一个快照只完整列出一次，之后都在内存里浏览：<code>ls</code> 慢在打开仓库，按文件夹 逐个去列，每点一下都要再付一次这个代价。交给 <code>--include</code> 的路径会先转义， 所以名叫 <code>photo[1].jpg</code> 的文件恢复出来的就是它自己，而不是这个通配符碰巧 匹配到的别的文件。</p><p>保留策略的几个选项，对应的是这些 keep 参数：</p><table tabindex="0"><thead><tr><th>选项</th><th>参数</th></tr></thead><tbody><tr><td>保留全部（默认）</td><td>根本不执行 <code>forget</code></td></tr><tr><td>保留一年</td><td><code>--keep-last 3 --keep-daily 7 --keep-weekly 5 --keep-monthly 12</code></td></tr><tr><td>保留一个月</td><td><code>--keep-last 3 --keep-daily 7 --keep-weekly 4</code></td></tr><tr><td>保留固定份数的备份</td><td><code>--keep-last N</code></td></tr></tbody></table><h2 id="密钥放在哪" tabindex="-1">密钥放在哪 <a class="header-anchor" href="#密钥放在哪" aria-label="Permalink to &quot;密钥放在哪&quot;">​</a></h2><p>仓库密码和存储密钥都在 macOS 钥匙串里。它们通过环境变量交给 restic： <code>RESTIC_PASSWORD</code>、<code>AWS_SECRET_ACCESS_KEY</code>、<code>RESTIC_REST_PASSWORD</code>， 从不经过命令行参数，也不落盘。</p><p>这份环境是从零拼出来的：只有 <code>PATH</code>、<code>HOME</code>、<code>TMPDIR</code>、<code>SSH_AUTH_SOCK</code>， 再加仓库地址和凭据。你会话里的其他变量一概不传。</p><h2 id="接入已有的仓库" tabindex="-1">接入已有的仓库 <a class="header-anchor" href="#接入已有的仓库" aria-label="Permalink to &quot;接入已有的仓库&quot;">​</a></h2><p>在选目的地那一步展开<strong>高级选项</strong>，勾上<strong>接入该位置上已有的备份仓库</strong>。 Keelhaven 会拿你的密码去验证，不会新建任何东西。</p><p>其他机器留下的快照原样保留，恢复窗口里会和 Keelhaven 自己的快照列在一起。</p><p>保留策略也不会动它们，从 0.9.2 起是这样。这之后的 <code>forget</code> 带着 <code>--tag keelhaven</code> 执行，只会处理 Keelhaven 自己创建的快照；restic 命令行或 别的工具写进去的，会一直留着，要清理得你自己动手。</p><p><strong>0.9.1 及更早的版本，会把保留策略用在仓库里的所有快照上。</strong> 如果仓库还有 别的东西在写，请先升级，再打开保留策略。</p><p><strong>一个仓库，只用一种保留策略。</strong> 每个计划给快照打的标签都一样，所以两个 Keelhaven 计划（或者两台装了 Keelhaven 的 Mac）共用一个仓库时，谁的保留 策略先跑，就会同时作用在两边。要么给每个计划单独一个仓库，要么把它们的 保留策略设成同一个。</p><h2 id="和命令行一起用" tabindex="-1">和命令行一起用 <a class="header-anchor" href="#和命令行一起用" aria-label="Permalink to &quot;和命令行一起用&quot;">​</a></h2><p>仓库地址就是你想的那样：</p><table tabindex="0"><thead><tr><th>目的地</th><th>地址</th></tr></thead><tbody><tr><td>文件夹或硬盘</td><td>路径本身</td></tr><tr><td>S3 兼容存储</td><td><code>s3:https://&lt;服务地址&gt;/&lt;存储桶&gt;/&lt;路径前缀&gt;</code></td></tr><tr><td>SFTP</td><td><code>sftp:&lt;用户名&gt;@&lt;主机&gt;:&lt;路径&gt;</code></td></tr><tr><td>REST 服务器</td><td><code>rest:http://&lt;主机&gt;:8000/</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sftp:backup@nas.local:/backups/mac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshots</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sftp:backup@nas.local:/backups/mac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Restored</span></span></code></pre></div><p>两边不会打架，restic 自己的锁管着。</p><h2 id="它开放了哪些参数" tabindex="-1">它开放了哪些参数 <a class="header-anchor" href="#它开放了哪些参数" aria-label="Permalink to &quot;它开放了哪些参数&quot;">​</a></h2><p>没有「额外参数」输入框，这是有意的：<code>--quiet</code> 或 <code>--verbose</code> 会破坏进度条 所依赖的 JSON 输出，<code>--no-lock</code> 会让「同一时间只跑一个」的保护失效。大家 常要的参数做成了有名字的设置项：</p><table tabindex="0"><thead><tr><th>设置项</th><th>restic 参数</th></tr></thead><tbody><tr><td>排除规则</td><td><code>--exclude</code></td></tr><tr><td>跳过缓存文件夹</td><td><code>--exclude-caches</code></td></tr><tr><td>内容没有变化时跳过备份</td><td><code>--skip-if-unchanged</code></td></tr><tr><td>不要备份挂载在这些文件夹里的其它磁盘</td><td><code>--one-file-system</code></td></tr><tr><td>不要先测量备份大小</td><td><code>--no-scan</code></td></tr><tr><td>预览本次备份</td><td><code>--dry-run</code></td></tr><tr><td>上传限速</td><td><code>--limit-upload</code></td></tr><tr><td>同时读取文件数</td><td><code>--read-concurrency</code></td></tr><tr><td>打包大小</td><td><code>--pack-size</code></td></tr></tbody></table><p>缺了你离不开的那个？<a href="https://github.com/shenxianpeng/keelhaven/issues/45" target="_blank" rel="noreferrer">告诉我们是哪个，用来做什么</a>。</p><h2 id="它不做什么" tabindex="-1">它不做什么 <a class="header-anchor" href="#它不做什么" aria-label="Permalink to &quot;它不做什么&quot;">​</a></h2><ul><li><strong>rclone 后端。</strong> 不支持 Google Drive、OneDrive、Dropbox：rclone 的凭据 存在钥匙串之外。<a href="https://github.com/shenxianpeng/keelhaven/issues/53" target="_blank" rel="noreferrer">原因写在这里</a>。</li><li><strong><code>restic mount</code>。</strong> 恢复窗口可以打开快照、在里面搜索、只恢复其中的文件， 但不能把快照挂载到访达里。</li><li><strong>默认配置之外的 rest-server</strong>：<code>--private-repos</code>、<code>--append-only</code>， 或自签名证书。</li></ul>`,28)])])}const g=e(o,[["render",s]]);export{k as __pageData,g as default};
